script:
export const meta = {
  name: 'review-shared-model-modules',
  description: 'Review shared/model-* modules for correctness bugs via parallel lensed reviewers plus adversarial verification',
  phases: [
    { title: 'Review' },
    { title: 'Verify' },
  ],
}

const FILES = [
  '/workspace/copilot-remote/shared/model-catalog-freshness.mjs',
  '/workspace/copilot-remote/shared/model-descriptors.mjs',
  '/workspace/copilot-remote/shared/model-id.mjs',
  '/workspace/copilot-remote/shared/model-refresh.mjs',
]

const CONTEXT_NOTE = `This review is READ-ONLY. Do not edit, write, or otherwise modify any file. Only use Read/Grep/Bash(read-only inspection) tools.

Target modules to review for CORRECTNESS BUGS (not style, not simplification):
${FILES.map(f => `- ${f}`).join('\n')}

For context, each module has a sibling test file (e.g. model-id.test.mjs) in the same shared/ directory — you may read those to understand intended behavior, but do not report bugs in the test files themselves, only in the four modules listed above. Also feel free to grep the wider repo (rg -n "modelId\\(" or similar) to see how these modules are actually called, since a "correctness bug" claim is much stronger when you can point at a real call site that would misbehave.`

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          file: { type: 'string', description: 'absolute path' },
          line: { type: 'number' },
          summary: { type: 'string', description: 'one sentence statement of the defect' },
          failure_scenario: { type: 'string', description: 'concrete input/state that triggers wrong output or a crash' },
        },
        required: ['file', 'summary', 'failure_scenario'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    refuted: { type: 'boolean', description: 'true if this is NOT a real bug (false positive, intended behavior, unreachable, etc.)' },
    reasoning: { type: 'string' },
  },
  required: ['refuted', 'reasoning'],
}

const LENSES = [
  {
    key: 'logic',
    prompt: `Review these modules for general logic/correctness bugs: wrong conditionals, off-by-one errors, incorrect boolean logic, wrong operator precedence, mis-ordered comparisons, incorrect return values, or logic that contradicts the module's apparent intent (infer intent from naming, comments, and the sibling test file).\n\n${CONTEXT_NOTE}`,
  },
  {
    key: 'async-error-handling',
    prompt: `Review these modules for async/concurrency/error-handling bugs: unhandled promise rejections, missing awaits, race conditions, incorrect error propagation/swallowing, incorrect use of try/catch, stale closures over mutable state, or timing assumptions that don't hold.\n\n${CONTEXT_NOTE}`,
  },
  {
    key: 'edge-cases-data',
    prompt: `Review these modules for edge-case and data-validation bugs: null/undefined handling, malformed or unexpected input shapes, boundary conditions (empty arrays/strings, zero, negative numbers), incorrect assumptions about external data (e.g. API responses, file contents, env vars), and mutation of shared/cached state that could leak across calls.\n\n${CONTEXT_NOTE}`,
  },
]

phase('Review')
const reviews = await parallel(LENSES.map(l => () =>
  agent(l.prompt, { label: `review:${l.key}`, phase: 'Review', schema: FINDINGS_SCHEMA })
))

const allFindings = reviews.filter(Boolean).flatMap(r => r.findings || [])
log(`${allFindings.length} raw findings from ${LENSES.length} reviewers, verifying each...`)

if (allFindings.length === 0) {
  return { confirmed: [], raw: [] }
}

phase('Verify')
const verified = await parallel(allFindings.map(f => () =>
  agent(
    `Adversarially verify this correctness-bug claim about ${f.file}${f.line ? ` (near line ${f.line})` : ''}.\n\nClaim: ${f.summary}\nAlleged failure scenario: ${f.failure_scenario}\n\nRead the actual file (and its sibling test file, and real call sites elsewhere in the repo if useful) and determine whether this is a REAL bug or a false positive. Be skeptical — default to refuted=true if you cannot concretely demonstrate the failure scenario actually occurs given the real code. Do not modify any files.`,
    { label: `verify:${f.file.split('/').pop()}`, phase: 'Verify', schema: VERDICT_SCHEMA }
  ).then(v => ({ ...f, verdict: v }))
))

const confirmed = verified.filter(Boolean).filter(v => v.verdict && v.verdict.refuted === false)

return { confirmed, totalRaw: allFindings.length, totalConfirmed: confirmed.length }
